-- ============================================
-- LUMA — Thème 5 : 3e scénario COURT x4 — Appeler les secours
-- ============================================


update scenarios set content = '{"characters": {"operator": "l''opérateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Your friend just fell hard while hiking and can''t get up. You dial emergency services.)", "text_fr": "(Votre ami vient de tomber violemment en randonnée et n''arrive pas à se relever. Vous composez les secours.)", "choices": [{"text": "(Stay calm and dial immediately.)", "text_fr": "(Reste calme et compose immédiatement.)", "next": "n2"}]}, "n2": {"speaker": "operator", "text": "Emergency services, what''s your emergency?", "text_fr": "Services d''urgence, quelle est votre urgence ?", "choices": [{"text": "My friend fell while hiking and can''t stand up, I think it''s his leg.", "text_fr": "Mon ami est tombé en randonnée et n''arrive pas à se lever, je pense que c''est sa jambe.", "next": "n3"}, {"text": "We need help — someone is badly injured on a hiking trail.", "text_fr": "On a besoin d''aide — quelqu''un est gravement blessé sur un sentier de randonnée.", "next": "n3"}]}, "n3": {"speaker": "operator", "text": "Okay, stay calm. Is he conscious and breathing normally?", "text_fr": "D''accord, restez calme. Il est conscient et respire normalement ?", "choices": [{"text": "Yes, he''s conscious and breathing fine, just in a lot of pain.", "text_fr": "Oui, il est conscient et respire bien, juste beaucoup de douleur.", "next": "n4"}, {"text": "Yes, conscious, but he seems to be in shock a little.", "text_fr": "Oui, conscient, mais il semble un peu en état de choc.", "next": "n4"}]}, "n4": {"speaker": "operator", "text": "Good. What''s your exact location or nearest landmark?", "text_fr": "Bien. Quelle est votre position exacte ou le point de repère le plus proche ?", "choices": [{"text": "We''re on Ridge Trail, about a mile past the second waterfall.", "text_fr": "On est sur Ridge Trail, à environ un mile après la deuxième cascade.", "next": "n5"}, {"text": "I can share my GPS location if that helps.", "text_fr": "Je peux partager ma position GPS si ça aide.", "next": "n5"}]}, "n5": {"speaker": "operator", "text": "That''s very helpful. Can you keep him still and warm while we dispatch a team?", "text_fr": "C''est très utile. Vous pouvez le garder immobile et au chaud pendant qu''on envoie une équipe ?", "choices": [{"text": "Yes, I have a jacket I can put over him.", "text_fr": "Oui, j''ai une veste que je peux mettre sur lui.", "next": "n6"}, {"text": "Yes, I''ll make sure he doesn''t move his leg.", "text_fr": "Oui, je vais m''assurer qu''il ne bouge pas sa jambe.", "next": "n6"}]}, "n6": {"speaker": "operator", "text": "Perfect. A rescue team is on the way, should arrive in about 20 minutes.", "text_fr": "Parfait. Une équipe de secours est en route, devrait arriver dans environ 20 minutes.", "choices": [{"text": "Thank you, should I stay on the line with you?", "text_fr": "Merci, je devrais rester en ligne avec vous ?", "next": "n7"}, {"text": "Understood, thank you so much for your help.", "text_fr": "Compris, merci beaucoup pour votre aide.", "next": "n7"}]}, "n7": {"speaker": "operator", "text": "Yes, please stay on the line in case anything changes.", "text_fr": "Oui, restez en ligne s''il vous plaît au cas où quelque chose change.", "choices": [{"text": "Okay, I''ll keep you updated on his condition.", "text_fr": "D''accord, je vous tiens informé de son état.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(A few minutes pass, you keep your friend calm and comfortable.)", "text_fr": "(Quelques minutes passent, vous gardez votre ami calme et confortable.)", "choices": [{"text": "(Reassure your friend that help is on the way.)", "text_fr": "(Rassure ton ami que les secours arrivent.)", "next": "n9"}]}, "n9": {"speaker": "operator", "text": "The rescue team should be visible soon — can you see them?", "text_fr": "L''équipe de secours devrait être visible bientôt — vous les voyez ?", "choices": [{"text": "Yes, I can see them approaching now!", "text_fr": "Oui, je les vois approcher maintenant !", "next": "end_rescued"}]}, "end_rescued": {"speaker": "operator", "text": "Great, they''ll take it from here. You did everything right.", "text_fr": "Super, ils prennent le relais maintenant. Vous avez tout fait comme il fallait.", "end": true, "ending_label": "Secours gérés avec sang-froid 🚑✅"}}}'::jsonb, is_playable = true
where title = 'Appeler les secours'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
